select upper(v) as u, concat(v, '!') as c, length(v) as l, char_length(v) as cl, substring(v, 1, 2) as sub, hex(vb) as h, unhex(v) as uh, concat(vb, 'x') as bc, lower(vb) as lv, repeat(v, 2) as r, v like 'a%' as lk, strcmp(v, 'a') as sc, ascii(v) as a, bin(whole) as bn, format(price, 1) as fm, inet_aton(v) as ia, uuid() as id, to_base64(vb) as b64, from_base64(v) as fb, convert(v using latin1) as cv, compress(v) as z, char(65) as ch, char(65 using utf8mb4) as chu, quote(v) as q, weight_string(v) as ws, aes_encrypt(v, 'k') as enc from everything
